style.css:
@-moz-document domain("pinterest.com") {
html, body {
    height: 100%;
    background: transparent !important;
  }

  /* Fondo de piel de leopardo */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    background-image: url("https://static4.depositphotos.com/1019221/338/i/450/depositphotos_3382879-stock-illustration-leopard-background.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: -9999;
    opacity: 1;
    pointer-events: none;
  }

  /* Contenedores transparentes */
  #__next, #root, .App, .AppContainer, [data-test-id="app-root"], div[role="main"] {
    background: transparent !important;
  }

  /* Cabecera y buscador en negro */
  header, .Header, .topNav, [data-test-id="header"], input[type="search"], .SearchBox, .searchBox {
    background: #000 !important;
    color: #fff !important;
    border-color: #000 !important;
  }

  /* Placeholder y textos en blanco */
  input[type="search"]::placeholder { color: #ccc !important; }
  header *, .Header *, .topNav *, .SearchBox * {
    color: #fff !important;
    fill: #fff !important;
  }

  /* Esquinas negras decorativas */
  #leopard-corner-top-left,
  #leopard-corner-top-right,
  #leopard-corner-bottom-left,
  #leopard-corner-bottom-right {
    position: fixed;
    width: 140px;
    height: 140px;
    z-index: 99999;
    background: #000;
    pointer-events: none;
  }
  #leopard-corner-top-left { top: 0; left: 0; border-bottom-right-radius: 140px; }
  #leopard-corner-top-right { top: 0; right: 0; border-bottom-left-radius: 140px; }
  #leopard-corner-bottom-left { bottom: 0; left: 0; border-top-right-radius: 140px; }
  #leopard-corner-bottom-right { bottom: 0; right: 0; border-top-left-radius: 140px; }

  /* Hacer los pines transparentes */
  .Pin, .Board, .gridItem, .searchResult {
    background: transparent !important;
  }
}
